function hit(attacker,target,damage,kind){let blocked=target.block&&!target.jump,actual=blocked?Math.ceil(damage*.22):damage;target.hp=clamp(target.hp-actual,0,100);target.stun=blocked?.14:(kind==='heavy'?.32:.22);target.vx+=attacker.face*(blocked?55:kind==='heavy'?190:135);target.hitFlash=blocked?.18:.36;attacker.meter=clamp(attacker.meter+(blocked?8:13),0,100);target.meter=clamp(target.meter+5,0,100);attacker.combo++;target.combo=0;comboCount=attacker.combo;comboUntil=now+1.05;addBurst((attacker.x+target.x)/2,FLOOR-target.y-105,blocked?'#c3eee0':attacker.accent,blocked?6:14,blocked?90:210);floating.push({x:target.x,y:FLOOR-target.y-165,text:blocked?'GUARDA!':String(actual),life:.8,color:blocked?'#b8e3cc':'#ffe3bd'});shake=blocked?3:7;if(!blocked&&!muted){try{let AC=window.AudioContext||window.webkitAudioContext;if(!window.audioCtx)window.audioCtx=new AC();let o=window.audioCtx.createOscillator(),g=window.audioCtx.createGain();o.type='triangle';o.frequency.setValueAtTime(kind==='heavy'?115:190,window.audioCtx.currentTime);o.frequency.exponentialRampToValueAtTime(55,window.audioCtx.currentTime+.12);g.gain.setValueAtTime(.12,window.audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,window.audioCtx.currentTime+.13);o.connect(g);g.connect(window.audioCtx.destination);o.start();o.stop(window.audioCtx.currentTime+.14);}catch{}}}
function pressed(k){return keys.has(k)&&!lastKeys.has(k)}
function getInput(f){if(f.id===0)return{left:keys.has('a'),right:keys.has('d'),jump:keys.has('w'),block:keys.has('s'),light:pressed('f'),heavy:pressed('g'),special:pressed('h'),dash:pressed('shift')};if(localMode)return{left:keys.has('arrowleft'),right:keys.has('arrowright'),jump:keys.has('arrowup'),block:keys.has('arrowdown'),light:pressed('1'),heavy:pressed('2'),special:pressed('3'),dash:pressed('0')};return null;}
function ai(f,o,dt){f.aiWait-=dt;let gap=Math.abs(o.x-f.x);if(f.stun>0||f.attack>0)return{};let toward=o.x>f.x?1:-1,input={left:gap>92&&toward<0,right:gap>92&&toward>0,block:o.attack>0&&gap<145&&Math.random()<.58};if(f.aiWait<=0){if(gap<100){let r=Math.random();if(r<.25)input.heavy=true;else if(r<.8)input.light=true;else input.block=true;}else if(gap<490&&f.meter>=100&&Math.random()<.52)input.special=true;else if(gap<220&&f.y===0&&Math.random()<.22)input.jump=true;else if(gap<250&&Math.random()<.2){input.dash=true;input.left=false;input.right=false;}f.aiWait=rand(.38,.95);}return input;}
function update(dt){now+=dt;if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)$('#message').classList.remove('show');}if(paused)return;if(roundResolved){transitionTimer-=dt;if(!matchOver&&transitionTimer<=0)resetRound();updateHud();return;}roundTimer=Math.max(0,roundTimer-dt);if(roundTimer===0)finishRound(fighters[0].hp===fighters[1].hp?-1:fighters[0].hp>fighters[1].hp?0:1);let[a,b]=fighters;a.face=b.x>a.x?1:-1;b.face=-a.face;
 for(let f of fighters){f.cool=Math.max(0,f.cool-dt);f.stun=Math.max(0,f.stun-dt);f.hitFlash=Math.max(0,f.hitFlash-dt*3);f.walk+=dt;f.block=false;if(f.attack>0){f.attack=Math.max(0,f.attack-dt);let p=1-f.attack/f.attackDuration;if(f.attackKind!=='special'&&!f.hitLanded&&p>.28&&p<.67){let o=f===a?b:a,range=f.attackKind==='heavy'?126:96;if(Math.abs(o.x-f.x)<range&&Math.abs(o.y-f.y)<100&&Math.sign(o.x-f.x)===f.face){hit(f,o,f.attackKind==='heavy'?15:8,f.attackKind);f.hitLanded=true;}}if(f.attack===0){f.attackKind='';if(!f.hitLanded)f.combo=0;}}
 if(f.stun<=0&&f.attack<=0){let inp=f.id===0||localMode?getInput(f):ai(f,a,dt);f.block=!!inp.block&&!f.jump;if(inp.dash){f.vx+=(inp.left?-1:inp.right?1:f.face)*310;addBurst(f.x,FLOOR-f.y-25,f.accent,7,90);}if(inp.jump&&!f.jump){f.vy=550;f.jump=true;}if(inp.left)f.vx-=680*dt;if(inp.right)f.vx+=680*dt;if(inp.light)startAttack(f,'light');if(inp.heavy)startAttack(f,'heavy');if(inp.special)startAttack(f,'special');}f.vx*=Math.pow(.001,dt);f.x=clamp(f.x+f.vx*dt,85,1195);if(f.jump||f.vy!==0){f.y+=f.vy*dt;f.vy-=1450*dt;if(f.y<=0){f.y=0;f.vy=0;f.jump=false;}}}
 if(Math.abs(a.x-b.x)<78){let m=(a.x+b.x)/2;a.x=m-39;b.x=m+39;}for(let p of projectiles){p.x+=p.vx*dt;p.life-=dt;let target=fighters[1-p.owner];if(Math.abs(target.x-p.x)<38&&Math.abs((FLOOR-target.y-100)-p.y)<95){hit(fighters[p.owner],target,24,'special');p.life=0;addBurst(p.x,p.y,p.color,23,250);}}projectiles=projectiles.filter(p=>p.life>0&&p.x>-80&&p.x<W+80);for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.98;p.vy-=250*dt;p.life-=dt;}particles=particles.filter(p=>p.life>0);for(let f of floating){f.y-=30*dt;f.life-=dt;}floating=floating.filter(f=>f.life>0);if(a.hp<=0)finishRound(1);else if(b.hp<=0)finishRound(0);if(comboUntil<now)comboCount=0;updateHud();}
function finishRound(winner){if(roundResolved)return;roundResolved=true;if(winner>=0){roundWins[winner]++;if(roundWins[winner]>=2){matchOver=true;showMessage(`${fighters[winner].name} VENCE!`,'A LENDA FOI ESCRITA',2.4);}else{showMessage(`${fighters[winner].name} VENCE O ROUND`,'PREPARE-SE PARA A PRÓXIMA LUTA',2);transitionTimer=2.1;}}else{showMessage('EMPATE','A ARENA PEDE MAIS',2);transitionTimer=2.1;}updateHud();}
function resetRound(){round++;roundResolved=false;roundTimer=99;fighters.forEach((f,i)=>Object.assign(f,{x:i?910:370,y:0,vx:0,vy:0,hp:100,meter:Math.max(0,f.meter-15),stun:0,attack:0,attackKind:'',cool:0,block:false,jump:false,hitFlash:0,combo:0,aiWait:.5}));projectiles=[];particles=[];floating=[];showMessage(`ROUND ${String(round).padStart(2,'0')}`,'LUTEM!',1.25);}
function updateHud(){for(let i=0;i<2;i++){let f=fighters[i];$(`#hp${i+1}`).style.width=`${f.hp}%`;$(`#sp${i+1}`).style.width=`${f.meter}%`;$(`#pct${i+1}`).textContent=`${Math.floor(f.meter)}%`;}$('#timer').innerHTML=`${String(Math.ceil(roundTimer)).padStart(2,'0')}<small>ROUND ${String(round).padStart(2,'0')}</small>`;$('#combo').classList.toggle('show',comboCount>1&&comboUntil>now);$('#combo').innerHTML=`${comboCount} <small>HIT COMBO</small>`;}
function render(t){ctx.clearRect(0,0,W,H);ctx.save();if(shake>0){ctx.translate(rand(-shake,shake),rand(-shake,shake));shake=Math.max(0,shake-.45);}background(t);for(let p of projectiles){ctx.save();ctx.globalCompositeOperation='lighter';let g=ctx.createRadialGradient(p.x,p.y,2,p.x,p.y,34);g.addColorStop(0,'#fff');g.addColorStop(.24,p.color);g.addColorStop(1,p.color+'00');ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,34,0,Math.PI*2);ctx.fill();ctx.strokeStyle=p.color;ctx.lineWidth=5;ctx.beginPath();ctx.ellipse(p.x,p.y,23,9,0,0,Math.PI*2);ctx.stroke();ctx.restore();}fighters.slice().sort((a,b)=>a.y-b.y).forEach(f=>drawFighter(f,t));for(let p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ellipse(ctx,p.x,p.y,p.size,p.size,p.color);}ctx.globalAlpha=1;for(let f of floating){ctx.globalAlpha=clamp(f.life,0,1);ctx.fillStyle=f.color;ctx.font='800 20px sans-serif';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y);}ctx.globalAlpha=1;ctx.restore();}
function frame(ts){let dt=Math.min(.033,(ts-last)/1000||0);last=ts;update(dt);render(ts/1000);lastKeys=new Set(keys);requestAnimationFrame(frame);}
function restart(){round=1;roundWins=[0,0];matchOver=false;roundResolved=false;transitionTimer=0;roundTimer=99;comboCount=0;particles=[];projectiles=[];floating=[];fighters.forEach((f,i)=>Object.assign(f,{x:i?910:370,y:0,vx:0,vy:0,hp:100,meter:0,stun:0,attack:0,attackKind:'',cool:0,block:false,jump:false,hitFlash:0,combo:0,aiWait:.5}));showMessage('FIGHT!','QUE A LENDA SEJA ESCRITA',1.35);updateHud();}
window.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys.add(k);if(k==='escape'){paused=!paused;$('#pauseBtn').textContent=paused?'▶　CONTINUAR':'Ⅱ　PAUSAR';if(!paused){$('#message').classList.remove('show');messageTimer=0;}else showMessage('PAUSADO','PRESSIONE ESC PARA CONTINUAR',999);}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
$('#pauseBtn').addEventListener('click',()=>{paused=!paused;$('#pauseBtn').textContent=paused?'▶　CONTINUAR':'Ⅱ　PAUSAR';if(paused)showMessage('PAUSADO','PRESSIONE ESC PARA CONTINUAR',999);else{$('#message').classList.remove('show');messageTimer=0;}});$('#restartBtn').addEventListener('click',restart);$('#modeBtn').addEventListener('click',()=>{localMode=!localMode;$('#modeBtn').textContent=localMode?'♟　2P LOCAL':'♟　1P VS CPU';showMessage(localMode?'2P LOCAL':'1P VS CPU',localMode?'REN: SETAS + 1 / 2 / 3':'AKIRA VS CPU',1.2);});$('#soundBtn').addEventListener('click',()=>{muted=!muted;$('#soundBtn').textContent=muted?'♫':'♪';$('#soundBtn').style.color=muted?'':'#e8bc78';});
updateHud();showMessage('FIGHT!','QUE A LENDA SEJA ESCRITA',1.5);requestAnimationFrame(frame);
</script>
